"""Бібліотека векторних об'єктів InterSlide (авторство ГС «УАІТ»): assets/library/<тема>/<id>.svg + index.json.
Сітка 64×64, штрих 3, круглі кінці. Кольори-мітки: C — основний, A — акцент, F — світла заливка;
застосунок підставляє кольори теми (library.recolor). Запуск: python tools/make_library.py"""
import json
import math
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / "shkola_office" / "assets" / "library"


TOK = {"C": "#010101", "A": "#020202", "F": "#030303"}     # мітки кольорів, library.recolor підміняє


def _a(c, fill):
    f = "none" if fill in (None, False) else fill
    return f'stroke="{TOK.get(c, c)}" fill="{TOK.get(f, f)}"'


def P(d, c="C", fill=None):
    return f'<path d="{d}" {_a(c, fill)}/>'


def R(x, y, w, h, c="C", r=4, fill="F"):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" {_a(c, fill)}/>'


def O(x, y, r, c="C", fill="F"):
    return f'<circle cx="{x}" cy="{y}" r="{r}" {_a(c, fill)}/>'


def E(x, y, rx, ry, c="C", fill="F"):
    return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" {_a(c, fill)}/>'


def L(*pts, c="C"):
    return f'<polyline points="{" ".join(f"{x},{y}" for x, y in pts)}" {_a(c, None)}/>'


def T(x, y, s, size=18, c="C", w=700):
    return f'<text x="{x}" y="{y}" font-family="Segoe UI, Arial, sans-serif" font-size="{size}" font-weight="{w}" ' \
           f'text-anchor="middle" fill="{TOK.get(c, c)}" stroke="none">{s}</text>'


def star(cx, cy, r1, r2, n=5, c="A", fill="A"):
    pts = []
    for i in range(2 * n):
        r = r1 if i % 2 == 0 else r2
        a = math.pi / n * i - math.pi / 2
        pts.append(f"{cx + r * math.cos(a):.1f},{cy + r * math.sin(a):.1f}")
    return f'<polygon points="{" ".join(pts)}" {_a(c, fill)}/>'


def poly(*pts, c="C", fill="F"):
    return f'<polygon points="{" ".join(f"{x},{y}" for x, y in pts)}" {_a(c, fill)}/>'


