def svg(body: str) -> str:
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="256" height="256" fill="none" '
            'stroke-width="3" stroke-linecap="round" stroke-linejoin="round">' + body + "</svg>")


def main() -> None:
    index = []
    for topic, items in LIB.items():
        d = OUT / topic
        d.mkdir(parents=True, exist_ok=True)
        for oid, title, tags, body in items:
            (d / f"{oid}.svg").write_text(svg(body), encoding="utf-8")
            index.append({"id": oid, "topic": topic, "title": title, "tags": tags, "file": f"{topic}/{oid}.svg"})
    (OUT / "index.json").write_text(json.dumps(index, ensure_ascii=False, indent=1), encoding="utf-8")
    (OUT / "LICENSES.md").write_text(
        "# Бібліотека InterSlide\n\nУсі об'єкти намальовані ГС «УАІТ» (tools/make_library.py), "
        "ліцензія як у застосунку «Офіс ШКОЛА». Сторонніх наборів поки немає; кожен новий вільний набір "
        "(MIT/ISC/CC0) — окремим рядком тут: назва, ліцензія, посилання.\n", encoding="utf-8")
    print(len(index), "об'єктів у", len(LIB), "темах ->", OUT)


if __name__ == "__main__":
    main()
